INSERT INTO eventos (titulo, descripcion, fecha, capacidad, estado) VALUES 
('Fiesta de Graduación', 'Celebra este importante logro académico con una fiesta memorable. Incluye animación profesional, música en vivo, servicios de catering y un ambiente festivo perfecto para compartir con compañeros, profesores y familia.', '2025-11-30 18:00:00', 120, 'publicado'),
('Fiesta de 15 Años', 'Una noche mágica y elegante para marcar un momento especial. Incluye decoración temática personalizada, vals tradicional, animación de calidad y servicio de banquete para crear recuerdos inolvidables.', '2025-08-15 19:00:00', 80, 'publicado'),
('Fiesta de Empresa', 'Fortalece el trabajo en equipo y celebra los logros anuales con estilo. Incluye presentaciones audiovisuales profesionales, cena formal, espacios de networking y entretenimiento para toda la empresa.', '2025-12-10 18:30:00', 200, 'publicado'),
('Boda', 'El día de tu vida merece ser perfecto. Nos encargamos de la decoración romántica, servicios de banquete, animación profesional, fotografia y todos los detalles para que vivas un momento inolvidable con tus seres queridos.', '2026-03-22 17:00:00', 150, 'publicado');
